import type {SessionEntry} from './session.js';
import type {SessionCursor} from './sessionStore.js';

export interface UserMessagePayload {
  type: 'user_message';
  content: string;
}

export interface PingMessage {
  type: 'ping';
  timestamp: number;
}

export interface ListSessionsMessage {
  type: 'list_sessions';
  limit?: number;
  before?: SessionCursor;
}

export type IncomingMessage = UserMessagePayload | PingMessage | ListSessionsMessage;

import type {IncomingMessage, ListSessionsMessage} from '../../types/messages.js';
import type {SessionCursor} from '../../types/sessionStore.js';

const MAX_CONTENT_LENGTH = 10000;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  switch (message.type) {
    case 'user_message':
      return validateUserMessage(message);
    case 'ping':
      return validatePingMessage(message);
    case 'list_sessions':
      return validateListSessionsMessage(message);
    default:
      return {valid: false, error: `Unknown message type: ${message.type}`};
  }
}

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  const trimmed = message.content.trim();

  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  if (!isValidOptionalLimit(message.limit)) {
    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
  }

  if (message.before === undefined) {
    return {valid: true, data: buildListSessionsMessage(message.limit, undefined)};
  }

  const cursor = parseBeforeCursor(message.before);
  if (cursor === undefined) {
    return {valid: false, error: 'list_sessions before must have a 1-128 char sessionId and valid updatedAt'};
  }

  return {valid: true, data: buildListSessionsMessage(message.limit, cursor)};
}

function isValidOptionalLimit(limit: unknown): limit is number | undefined {
  if (limit === undefined) return true;
  if (typeof limit !== 'number') return false;
  return Number.isInteger(limit) && limit >= 0;
}

function parseBeforeCursor(rawBefore: unknown): SessionCursor | undefined {
  if (typeof rawBefore !== 'object' || rawBefore === null) return undefined;
  if (Array.isArray(rawBefore)) return undefined;

  const candidate = rawBefore as Record<string, unknown>;
  if (!isValidCursorSessionId(candidate.sessionId)) return undefined;
  if (!isValidCursorTimestamp(candidate.updatedAt)) return undefined;

  return {updatedAt: candidate.updatedAt, sessionId: candidate.sessionId};
}

function buildListSessionsMessage(limit: number | undefined, before: SessionCursor | undefined): ListSessionsMessage {
  const frame: ListSessionsMessage = {type: 'list_sessions'};
  if (limit !== undefined) frame.limit = limit;
  if (before !== undefined) frame.before = before;
  return frame;
}

function isValidCursorSessionId(sessionId: unknown): sessionId is string {
  if (typeof sessionId !== 'string') return false;
  const maxLength = 128;
  return sessionId.length > 0 && sessionId.length <= maxLength;
}

function isValidCursorTimestamp(updatedAt: unknown): updatedAt is string | number {
  if (typeof updatedAt === 'number') return Number.isFinite(new Date(updatedAt).getTime());
  if (typeof updatedAt === 'string') return Number.isFinite(Date.parse(updatedAt));
  return false;
}

